<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import type { BookApi } from '../api/writing'
import type { Chapter, WritingAgentSelection } from '../../../desktop/src/contracts/index'
import type { DocumentSnapshot } from '../../../desktop/src/contracts/document-review/types'
import type { DocumentAnnotation } from '../../../desktop/src/contracts/document-review/annotations'
import { locateTextAnchor } from '../../../desktop/src/contracts/document-review/anchors'
import { messageOf } from '../api/http'
import { DraftStore } from './drafts'
const props = defineProps<{ api: BookApi; owner: string; chapter: Chapter; selection?: WritingAgentSelection; locked: boolean }>()
const emit = defineEmits<{ locate: [start: number, end: number] }>()
const snapshot = ref<DocumentSnapshot | null>(null), items = ref<DocumentAnnotation[]>([]), cursor = ref<number | null>(null), body = ref(''), busy = ref(false), error = ref(''), recovery = ref<string | null>(null)
const store = new DraftStore(sessionStorage, props.owner, props.api.id)
let epoch = 0, operation = crypto.randomUUID()
const key = () => `annotation:${props.chapter.id}`
watch(body, value => { if (!value) return; try { store.write(key(), props.chapter.revision || '', value) } catch { error.value = '恢复空间不足，请复制批注意见。' } })
async function load(more = false) { const token = epoch; busy.value = true; try { const current = snapshot.value || await props.api.snapshot({ workItemId: props.api.id, kind: 'body', legacyId: props.chapter.id }); if (token !== epoch) return; snapshot.value = current; const page = await props.api.annotations(current.ref, more ? cursor.value ?? undefined : undefined); if (token !== epoch) return; items.value = more ? [...items.value, ...page.items] : page.items; cursor.value = page.nextCursor } catch (e) { if (token === epoch) error.value = messageOf(e) } finally { if (token === epoch) busy.value = false } }
watch(() => [props.chapter.id, props.chapter.revision], () => { epoch++; snapshot.value = null; items.value = []; error.value = ''; const copy = store.read<string>(key()); recovery.value = copy && typeof copy.data === 'string' && copy.data ? copy.data : null; body.value = ''; operation = crypto.randomUUID(); void load() }, { immediate: true })
const selected = computed(() => props.selection && props.selection.text && props.chapter.content.slice(props.selection.start, props.selection.end) === props.selection.text ? props.selection : null)
async function create() { if (!selected.value || !snapshot.value || props.locked || busy.value) return; const token = epoch, sent = body.value; busy.value = true; error.value = ''; try { await props.api.annotate({ document: snapshot.value.ref, operationId: operation, expectedRevision: props.chapter.revision!, expectedDraftRevision: null, title: props.chapter.title, draftText: props.chapter.content, start: selected.value.start, end: selected.value.end, body: sent }); if (token !== epoch) return; operation = crypto.randomUUID(); if (body.value === sent) { body.value = ''; store.remove(key()) }; await load() } catch (e) { if (token === epoch) error.value = messageOf(e) } finally { if (token === epoch) busy.value = false } }
async function change(item: DocumentAnnotation, action: 'resolve' | 'reopen' | 'remove') { if (props.locked || !snapshot.value || busy.value) return; const token = epoch; busy.value = true; try { await props.api.changeAnnotation(action, { document: snapshot.value.ref, id: item.id, expectedAnnotationRevision: item.revision, operationId: crypto.randomUUID() }); if (token === epoch) await load() } catch (e) { if (token === epoch) error.value = messageOf(e) } finally { if (token === epoch) busy.value = false } }
function locate(item: DocumentAnnotation) { const position = locateTextAnchor(props.chapter.content, item.anchor); if (position.status !== 'located') { error.value = '原文已变化，无法可靠定位这条批注。'; return }; emit('locate', position.start, position.end) }
onBeforeUnmount(() => { epoch++ })
</script>
<template><details class="annotations-panel paper-card"><summary>正文批注（{{ items.length }}）</summary><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="locked" class="muted">请先保存正文并完成输入，再新增或处理批注。</p><aside v-if="recovery" class="recovery-note">有未保存的批注意见。<button @click="body = recovery; recovery = null">恢复意见</button></aside><form @submit.prevent="create"><p class="muted">{{ selected ? `已选择：${selected.text.slice(0, 100)}` : '在正文中选中文字，为它添加批注。' }}</p><label>批注意见<textarea v-model="body" rows="3" required maxlength="10000"></textarea></label><button :disabled="busy || locked || !selected || !body.trim()">保存批注</button></form><article v-for="item in items" :key="item.id" class="event-card"><button @click="locate(item)">{{ item.anchor.quote.slice(0, 100) }}</button><p>{{ item.body }}</p><div class="button-row"><span>{{ item.status === 'resolved' ? '已解决' : '待处理' }}</span><button :disabled="busy || locked" @click="change(item, item.status === 'open' ? 'resolve' : 'reopen')">{{ item.status === 'open' ? '标为已解决' : '重新打开' }}</button><button :disabled="busy || locked" @click="change(item, 'remove')">移除批注</button></div></article><button v-if="cursor !== null" :disabled="busy" @click="load(true)">更多批注</button></details></template>
